            aOrbiterC = ((aOrbiterC + aOrbiterE) + 0x2D6D17AF6D5054CDULL) + aOUSaltF[((aIndex + 189U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterC) ^ 0xFE931D5FBEF39DEAULL) ^ aNonceWordA;
