            aWandererF = aWandererF ^ (((RotL64(aScatter, 28U) + RotL64(aOrbiterA, 53U)) + aOrbiterG) + aWUSaltF[((aIndex + 353U)) & S_SALT1]);
            aWandererA = aWandererA + (((RotL64(aPrevious, 37U) + RotL64(aOrbiterC, 35U)) + aOrbiterH) + aWUSaltD[(((511U - aIndex) + 37U)) & S_SALT1]);
