            //
            aIngress = (RotL64(aFuseLaneC[((aIndex + 30468U)) & S_BLOCK1], 21U) ^ RotL64(aFuseLaneA[((aIndex + 27920U)) & S_BLOCK1], 39U));
            aIngress ^= (RotL64(aSource[((aIndex + 31261U)) & S_BLOCK1], 5U) ^ RotL64(aSoilLaneB[((S_BLOCK1 - aIndex + 32550U)) & S_BLOCK1], 51U));
