            aScatter = TwistMix64::DiffuseB(((aScatter ^ aSeedDomainWordScatter) ^ aNonceWordC));
            //
            aOrbiterJ = ((aWandererE + RotL64(aCross, 29U)) + 0x2E8B93045D37752AULL) + aNonceWordG;
            aOrbiterA = ((aWandererH + RotL64(aIngress, 41U)) + 0x2D41C7BB19A7A8B3ULL) + aNonceWordE;
            aOrbiterF = ((aWandererB + RotL64(aScatter, 14U)) + RotL64(aCarry, 35U)) + 0xD5EE36A4B7A7219FULL;
            aOrbiterI = ((aWandererI + RotL64(aPrevious, 37U)) + 0xEF426A2D0185B972ULL) + aOASaltH[((aIndex + 55U)) & S_SALT1];
            aOrbiterK = ((aWandererJ + RotL64(aCross, 11U)) + 0xE2FA3F33237266D9ULL) + aOASaltB[(((511U - aIndex) + 23U)) & S_SALT1];
            aOrbiterE = (aWandererK + RotL64(aIngress, 23U)) + 0x91BF4EC0FB8BDE1CULL;
            aOrbiterG = (((aWandererG + RotL64(aScatter, 19U)) + RotL64(aCarry, 21U)) + 0xA1663F5E5EE43707ULL) + aNonceWordA;
            aOrbiterB = (aWandererF + RotL64(aPrevious, 46U)) + 0x713A6307212A83BCULL;
            aOrbiterH = ((aWandererC + RotL64(aCross, 35U)) + 0x42707CB4755C9E73ULL) + aOASaltD[(((511U - aIndex) + 309U)) & S_SALT1];
            aOrbiterC = ((aWandererD + RotL64(aIngress, 53U)) + RotL64(aCarry, 47U)) + 0xEFD3F19CC86AE470ULL;
            aOrbiterD = ((aWandererA + RotL64(aScatter, 43U)) + 0xABD85096C185560BULL) + aNonceWordB;
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0xC46A4C44A0F95423ULL;
