            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0x15DCC7D5D5EF2AE5ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterI) ^ 0xD359D2C161E47E42ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x5078DA646986E12DULL), 11U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0x5AEF745138E685ACULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0xB9B9E7B9928984A5ULL;
