            //
            aOrbiterH = ((aOrbiterH + aOrbiterC) + 0x4B30AAC9457A6A6FULL) + aNonceWordO;
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0xA08E7BF9AF684829ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x7AE994CB05C82FCDULL), 27U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterG) + 0xE86AB8545B4D8109ULL) + aOUSaltB[((aIndex + 228U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0x85A2D0FCD3CAD4AFULL;
            aOrbiterA = RotL64((aOrbiterA * 0x842303CE3EEAEEA7ULL), 23U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterB) + 0x6D195CE9AF25D9EFULL) + aOUSaltF[(((511U - aIndex) + 82U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0xEFDE2D4FBB313A63ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x7091816BF3A4AFEBULL), 57U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterI) + 0xCDB596AFA9EA259BULL) + aOUSaltA[((aIndex + 29U)) & S_SALT1];
            aOrbiterK = (((aOrbiterK ^ aOrbiterA) ^ 0x71E5AA5551F6D0BDULL) ^ aOUSaltE[(((511U - aIndex) + 177U)) & S_SALT1]) ^ aNonceWordI;
            aOrbiterK = RotL64((aOrbiterK * 0x84963C5F2E6B4681ULL), 47U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0xD5528F58E67E2A14ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0x7C287AE08E58DDFDULL;
            aOrbiterC = RotL64((aOrbiterC * 0xE94A8BBEE9155183ULL), 13U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterJ) + 0x956F605A759AFE09ULL) + aOUSaltC[((aIndex + 321U)) & S_SALT1];
