            //
            aOrbiterB = ((aOrbiterB + aOrbiterH) + 0x5BD37E12D5AF98B4ULL) + aOUSaltD[(((511U - aIndex) + 334U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0xF073B81A50378529ULL;
