            aIngress = aIngress + (aOrbiterJ ^ RotL64(aOrbiterC, 19U));
            aIngress = aIngress + (aOrbiterD ^ RotL64(aOrbiterI, 47U));
            aIngress = aIngress + RotL64(aOrbiterA, 39U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererA = aWandererA ^ (((RotL64(aPrevious, 5U) + RotL64(aOrbiterA, 26U)) + aOrbiterH) + aNonceWordH);
            aWandererC = aWandererC + (((RotL64(aCross, 34U) + RotL64(aOrbiterK, 3U)) + aOrbiterC) + aWUSaltA[((aIndex + 52U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((RotL64(aIngress, 13U) + RotL64(aOrbiterB, 13U)) + aOrbiterE);
            aWandererK = aWandererK + (((RotL64(aScatter, 51U) + aOrbiterJ) + RotL64(aOrbiterG, 47U)) + aNonceWordL);
            aWandererE = aWandererE ^ ((RotL64(aPrevious, 43U) + aOrbiterD) + RotL64(aOrbiterA, 23U));
            aWandererH = aWandererH + ((((RotL64(aCross, 46U) + aOrbiterF) + RotL64(aOrbiterB, 43U)) + RotL64(aCarry, 11U)) + aWUSaltD[(((511U - aIndex) + 427U)) & S_SALT1]);
            aWandererI = aWandererI ^ (((RotL64(aIngress, 27U) + aOrbiterH) + RotL64(aOrbiterJ, 11U)) + aWUSaltH[((aIndex + 383U)) & S_SALT1]);
            aWandererF = aWandererF + (((RotL64(aScatter, 21U) + aOrbiterG) + RotL64(aOrbiterK, 57U)) + aWUSaltB[(((511U - aIndex) + 284U)) & S_SALT1]);
            aWandererD = aWandererD ^ (((RotL64(aPrevious, 3U) + RotL64(aOrbiterE, 53U)) + aOrbiterD) + aNonceWordK);
            aWandererG = aWandererG + ((((RotL64(aCross, 57U) + RotL64(aOrbiterI, 51U)) + aOrbiterF) + aNonceWordM) + aWUSaltC[((aIndex + 424U)) & S_SALT1]);
            aWandererB = aWandererB ^ (((RotL64(aIngress, 29U) + RotL64(aOrbiterC, 6U)) + aOrbiterI) + RotL64(aCarry, 57U));
            //
            aCarry = aCarry + (RotL64(aWandererE, 39U) ^ aWandererI);
            aCarry = aCarry + (aWandererH ^ RotL64(aWandererK, 54U));
            aCarry = aCarry + (aWandererF ^ RotL64(aWandererG, 23U));
            aCarry = aCarry + (aWandererA ^ RotL64(aWandererJ, 19U));
            aCarry = aCarry + (aWandererB ^ RotL64(aWandererC, 43U));
            aCarry = aCarry + RotL64(aWandererD, 11U);
            aCarry = aCarry + RotL64(aIngress, 36U);
