            aCross ^= (RotL64(aHeartLaneA[((S_BLOCK1 - aIndex + 91U)) & S_BLOCK1], 41U) ^ RotL64(aSoilLaneC[((aIndex + 1559U)) & S_BLOCK1], 53U));
