            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterF = (aWandererF + RotL64(aScatter, 5U)) + 0xEF603F15256AE165ULL;
            aOrbiterJ = (((aWandererG + RotL64(aPrevious, 11U)) + RotL64(aCarry, 53U)) + 0x2E7098ED8ED7DB8DULL) + aOASaltD[(((511U - aIndex) + 365U)) & S_SALT1];
            aOrbiterE = (aWandererH + RotL64(aCross, 51U)) + 0xFAB5562119B6B788ULL;
            aOrbiterB = (aWandererB + RotL64(aIngress, 3U)) + 0xBC7C77B3CC3702ABULL;
